import{_ as s,l as o,o as e,c as n,v as t,p as d,x as r,d as l,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"约束与触发器","description":"","frontmatter":{"title":"约束与触发器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/constraints-triggers.md","filePath":"cs/constraints-triggers.md","lastUpdated":1789023840000}'),E={name:"cs/constraints-triggers.md"};function h(A,a,_,m,u,f){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="约束与触发器" tabindex="-1">约束与触发器 <a class="header-anchor" href="#约束与触发器" aria-label="Permalink to &quot;约束与触发器&quot;">​</a></h1><div class="epigraph"><p>约束是声明的不变式，拒绝违反它的状态；触发器是事件上的过程，能维护、能通知，也能把语义藏进过程体。</p><footer>—— 据 Codd 完整性；Widom and Finkelstein 主动数据库；Gray and Reuter；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/outer-semi-join">上一课</a>把读侧的连接族补齐。本课不重讲 NULL 填充。缺口是<strong>写路径上的含义</strong>：键、外键、检查条件如何在语句边界成立，以及触发器如何在插入更新删除时自动开火。主干 <a href="/cs/keys-integrity">键与完整性</a>、<a href="/cs/fk-actions">外键动作</a> 已给声明约束；进阶对照过程式触发器，避免把两者混成「都是规则」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>声明约束：主键、唯一、外键、<code>CHECK</code>、<code>NOT NULL</code>。引擎在 DML 后（或延迟到提交）检查，失败则语句或事务失败。这是不变式，优化器有时还能用约束改写查询（唯一则基数至多一）。缺口是：有些维护写不进约束——写审计行、同步冗余列、级联之外的业务。触发器绑定事件（BEFORE/AFTER、行级/语句级），过程体再写 SQL 或过程语言。</p><p>主动数据库把规则写成「事件–条件–动作」（ECA）。触发器是工程落地。危险是递归触发、顺序依赖、与约束检查的交错顺序因产品而异。本课钉分类，不背每家手册。</p><p><span class="marginnote">延迟约束：可先插入互相引用的两行，提交时再查外键。触发器通常不能「延迟到提交才想起来语义」而不留下中间可见状态——可见性仍受隔离级别约束。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>约束：模式对象，查询优化可假设它们永真。触发器：过程，优化器一般看不见体内部的代数。维护冗余（如缓存合计）可用触发器，也可用后课物化视图刷新；前者灵活，后者有机会增量计划。</p><p>级联外键是声明动作，不是触发器；实现上可能走同一套内部触发机制，对用户仍应是约束语义。本课不把内部实现当用户模型。</p>',10)),(e(),d(p,null,{default:r(()=>[c(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DML%5B%22%E6%8F%92%E5%85%A5%20%2F%20%E6%9B%B4%E6%96%B0%20%2F%20%E5%88%A0%E9%99%A4%22%5D%20--%3E%20TRG%5B%22%E8%A7%A6%E5%8F%91%E5%99%A8%20ECA%22%5D%0A%20%20DML%20--%3E%20CST%5B%22%E5%A3%B0%E6%98%8E%E7%BA%A6%E6%9D%9F%E6%A3%80%E6%9F%A5%22%5D%0A%20%20CST%20--%3E%20OK%5B%22%E6%8E%A5%E5%8F%97%22%5D%0A%20%20CST%20--%3E%20FAIL%5B%22%E5%9B%9E%E6%BB%9A%E8%AF%AD%E5%8F%A5%E6%88%96%E4%BA%8B%E5%8A%A1%22%5D%0A%20%20TRG%20--%3E%20MORE%5B%22%E6%9B%B4%E5%A4%9A%20DML%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>检查时机：立即约束在语句末；延迟在提交。触发器嵌套时，约束可能看到触发器造成的中间行。写偏斜一类异常仍是并发课的对象；约束不自动给出可串行。</p><p>失败处理：约束失败有标准的事务后果；触发器里自己吞掉错误会破坏「不变式总成立」。主干把声明约束当默认完整性通道，触发器当无法声明时的补充。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲存储过程的模块系统、包与权限模型——下一课存储过程。也不把触发器当消息总线或跨库工作流。递归深度限制是产品参数，不是理论原语。</p><p>后课默认：能写成约束的不要藏进触发器。触发器有副作用，去相关与下推都把它们当防火墙。保存点与过程体里的部分回滚是再下一课。</p><p>完整性首先是模式上的断言。过程是补充，不是另一套关系理论。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>约束声明不变式；触发器是 ECA 过程，优化器通常看不见。</li><li>级联外键是声明动作；延迟约束在提交时检查。</li><li>存储过程下一课：可调用的过程模块，不只绑在事件上。</li><li>出处：Codd；Widom and Finkelstein；Gray and Reuter；Ramakrishnan and Gehrke。</li></ul>',9))])}const k=s(E,[["render",h]]);export{B as __pageData,k as default};
